<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import AppDialog from './AppDialog.vue';
type Link={aditivo:string;base:string|null;justificativa:string;revisao:number};
const props=defineProps<{documents:Array<{numero_registro:string;tipo:string}>;links:Link[];request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>}>();
const emit=defineEmits<{close:[];saved:[message:string]}>();
const amendments=computed(()=>props.documents.filter(item=>/aditivo/i.test(item.tipo)&&/conven[çc][ãa]o coletiva/i.test(item.tipo)));
const bases=computed(()=>props.documents.filter(item=>!/aditivo/i.test(item.tipo)&&/conven[çc][ãa]o coletiva/i.test(item.tipo)));
const amendment=ref(''),base=ref(''),reason=ref(''),revision=ref(0),busy=ref(false),error=ref('');let alive=true;
const current=computed(()=>props.links.find(item=>item.aditivo===amendment.value));
watch(amendment,()=>{base.value=current.value?.base??'';revision.value=current.value?.revisao??0;reason.value='';error.value='';});
async function save(){if(busy.value||!amendment.value||reason.value.trim().length<8)return;busy.value=true;error.value='';try{await props.request('/api/contexto/vinculos','POST',{aditivo:amendment.value,base:base.value||null,justificativa:reason.value.trim(),revisao:revision.value});if(alive)emit('saved',base.value?'Vínculo do aditivo atualizado.':'Aditivo marcado como não vinculado.');}catch(cause){if(alive)error.value=(cause as Error).message;}finally{if(alive)busy.value=false;}}
onBeforeUnmount(()=>{alive=false;});
</script>
<template><AppDialog title="Gerenciar vínculos de aditivos" :busy="busy" @close="emit('close')"><p>Associe cada aditivo à sua convenção coletiva para compor a consolidação deste escritório.</p><p v-if="!amendments.length" role="status">Ainda não há aditivos de convenção coletiva disponíveis.</p><form v-else class="vue-form" @submit.prevent="save"><label>Aditivo<select v-model="amendment" required :disabled="busy"><option value="">Selecione um aditivo</option><option v-for="item in amendments" :key="item.numero_registro">{{ item.numero_registro }}</option></select></label><template v-if="amendment"><article class="document-related"><small>Decisão registrada</small><p>{{ current?.base?'Vinculado à CCT '+current.base:current?'Não vinculado':'Ainda não avaliado' }}</p><p v-if="current?.justificativa">{{ current.justificativa }}</p></article><label>CCT de destino<select v-model="base" :disabled="busy"><option value="">Rejeitar ou remover vínculo</option><option v-for="item in bases" :key="item.numero_registro">{{ item.numero_registro }}</option></select></label><label>Justificativa da decisão<textarea v-model="reason" required minlength="8" maxlength="2000" :disabled="busy"></textarea></label><p>A alteração exige atualizar a consolidação antes de revisar ou gerar relatórios finais.</p></template><p v-if="error" role="alert">{{ error }} Feche e atualize a lista antes de tentar novamente se o vínculo foi alterado em outra aba.</p><footer><button class="secondary" type="button" :disabled="busy" @click="emit('close')">Cancelar</button><button class="primary" type="submit" :disabled="busy||!amendment||reason.trim().length<8">{{ busy?'Salvando…':'Salvar decisão' }}</button></footer></form></AppDialog></template>
